def upgrade() -> None:
    """Create the captured runtime schema."""
    op.execute("PRAGMA foreign_keys=OFF")
    for _table_name, ddl in TABLE_SQL:
        op.execute(ddl)
    op.execute("PRAGMA foreign_keys=ON")



def downgrade() -> None:
    """Drop the captured runtime schema in reverse order."""
    op.execute("PRAGMA foreign_keys=OFF")
    for table_name in DROP_ORDER:
        op.execute(f"DROP TABLE IF EXISTS {table_name}")
    op.execute("PRAGMA foreign_keys=ON")
